/** ===== Query helpers ===== */
function normalizeTerms(terms) {
  const all = [], none = [], changed = [];
  for (const t of terms) {
    if (!t) continue;
    if (t.kind === $NOT) none.push(t.Comp);
    else if (t.kind === $CHANGED) changed.push(t.Comp);
    else all.push(t);
  }
  const cacheKey = all.map(c => c.key.description || 'c').sort().join('|') || '*';
