  world.install(extension);

  world.emit("x", {});
  assert.equal(handled, 1);

  assert.equal(world.uninstall(extension), true);
  assert.equal(cleaned, 1);

  world.emit("x", {});
  assert.equal(handled, 1);

  assert.equal(world.uninstall(extension), false);
}
```

