        world.time = Number.isFinite(t) ? t : 0;
      }
      if (Object.prototype.hasOwnProperty.call(data.meta, 'frame')) {
        const f = Number(data.meta.frame);
        world.frame = Number.isFinite(f) ? (f | 0) : 0;
      }
    }
    return world;
  }
}

